// 钱搜索函数
int CheinSearch(poly g, int *ans)
{
    int index = 0;
    int temp = 0;
    for (int i = 1; i <= 1023; i++)
    {
        temp = 0;
        for (int j = 0; j <= g.ci; j++)
        {
            temp = Add(temp, (Mul(g.num[j], Pow(exp[i], j))));
        }
        if (temp == 0)
