        max_num.num[max_num.ci] = Div(a.num[a.ci], b.num[b.ci]); // 得到最高次项的数据
        poly temp;
        temp = poly_Mul(max_num, b);
        a = poly_Sub(a, temp);
        shang = poly_Sub(shang, max_num);
