## 例题2.5 叠筐
[题目链接](http://acm.hdu.edu.cn/showproblem.php?pid=2074)

求解排版题的新思路：当输出的图形具有的规律不能或者很难直接应用到输出时，应该首先用一个缓存数组来保存将要输出的字符阵列，然后在该数组上完成排版，最后按照排版输出整个图形。

```cpp
#include <bits/stdc++.h>
using namespace std;
int main()
{
    int num=0;//输入的奇数
    int count = 0;//记录输出了多少次
    char center,outside;
    char rect[100][100];
    while(scanf("%d %c %c",&num,&center,&outside)!=EOF){
        if(num%2==0){
            printf("error");
        }
        else{
            char insert=NULL;
            //中心赋值
            int center_index=num/2;
            rect[center_index][center_index]=center;
            //循环插入外边框
            for(int i=1;i<=num/2;i++){
                if(i%2==1){
                    insert = outside;
                }
                else{
                    insert = center;
                }
                //插入横向
                for(int k=center_index-i;k<=center_index+i;k++){
                    rect[center_index-i][k]=insert;
                    rect[center_index+i][k]=insert;
                }
                //插入纵向
                for(int k=center_index-i+1;k<=center_index+i-1;k++){
                    rect[k][center_index-i]=insert;
                    rect[k][center_index+i]=insert;
                }
                //去除四角
                rect[0][0]=' ';
                rect[0][num-1]=' ';
                rect[num-1][0]=' ';
                rect[num-1][num-1]=' ';
            }
            //输出图案
            if(count==0){
                for(int i=0;i<num;i++){
                    for(int j=0;j<num;j++){
                        printf("%c",rect[i][j]);
                    }
                    printf("\n");
                    count=1;
                }
            }
            else{
                printf("\n");
                for(int i=0;i<num;i++){
                    for(int j=0;j<num;j++){
                        printf("%c",rect[i][j]);
                    }
                    count=1;
                }
            }
        }
    }
    return 0;
}
```

