int main(){
    int n;
    scanf("%d",&n);
    int list[1010];
    for(int i=0;i<n;i++)
    {
        scanf("%d",&list[i]);
    }
    int x,flag=0;
    scanf("%d",&x);
    for(int k=0;k<n-1;k++)
    {
        for(int j=k+1;j<n;j++)
