int main()
{
    priority_queue<int> q;
    q.push(1);
    q.push(2);
    q.push(4);
    q.push(3);
    printf("%d\n",q.top());
    q.pop();
    printf("%d\n",q.top());
    system("pause");// 防止运行后自动退出，需头文件stdlib.h
    return 0;
}
```
+ 输出：
```text
4
3
```
