#include <utility>
#include <map>
#include <algorithm>
using namespace std;
//主函数
int main()
{
    int x = 1,y = -2;
    printf("%d %d\n",max(x,y),min(x,y));
    printf("%d %d\n",abs(x),abs(y));
    system("pause");// 防止运行后自动退出，需头文件stdlib.h
    return 0;
}
```
+ 输出：
```text
