//比较函数
bool cmp(int a,int b)//vector中的元素为int型
{
    return a>b;//从大到小
}
//主函数
int main()
{
    vector<int> vi;
    vi.push_back(2);
    vi.push_back(3);
    vi.push_back(1);
    sort(vi.begin(),vi.end(),cmp);
    for(int i=0;i<3;i++)
    {
        printf("%d ",vi[i]);
    }
    system("pause");// 防止运行后自动退出，需头文件stdlib.h
    return 0;
}
```
+ 输出：
```text
3 2 1 
```
+ 以 `string` 为例：
