    if(n==1)
    {
        printf("%c->%c\n",from,to);
    }
    else
    {
        hanoi(n-1,from,mid,to);//要想移动n级汉诺塔需要先移动n-1级汉诺塔到另一边
        printf("%c->%c\n",from,to);//把最后最大的一块移动到目的位置
