例题：[有限制的选数II](https://sunnywhy.com/sfbj/4/3/141)
+ 代码：
```cpp
#include <cstdio>
#include <cstring>
#include <iostream>
#include <algorithm>
#include <cmath>
#include <string>
#include <vector>
using namespace std;
const int MAX = 15;
int n,k,ans=0;
int num[MAX];
//递归函数求解有限制的选数
void F(int index,int sum)
{
    //递归边界
    if(index==n)
    {
        if(sum==k)
            ans++;
        return;
    }
    //递归式
    for(int i=0;i<=(k-sum)/num[index];i++)//在循环中加上了本身的数据
    {
        F(index+1,sum+i*num[index]);//根据加上了本身的数据再继续往后递归
    }
}
//主函数
int main(){
    scanf("%d %d",&n,&k);
    for(int i=0;i<n;i++)
    {
        scanf("%d",&num[i]);
    }
    F(0,0);
    printf("%d",ans);
    system("pause");// 防止运行后自动退出，需头文件stdlib.h
    return 0;
}
```
+ 总结：这道题目的巧妙之处在于设计了在循环中加上了**本身的数据**，随后根据加上了本身的数据再继续往后递归。

例题：[有限制的选数III](https://sunnywhy.com/sfbj/4/3/142)
+ 代码：
```cpp
#include <cstdio>
#include <cstring>
#include <iostream>
#include <algorithm>
#include <cmath>
#include <string>
#include <vector>
using namespace std;
const int MAX = 15;
const int MAXN = 150;
int n,k,ans=0,m;
int num[MAX],p[MAX];
int hashTable[MAXN] = {0};
//递归函数求解有限制的选数
void F(int index,int sum)
{
    //递归边界
    if(index==m)
    {
        if(sum==k)
            ans++;
        return;
    }
    //递归式
    for(int i=0;i<=min((k-sum)/p[index],hashTable[p[index]]);i++)//去除重复数据
    {
        F(index+1,sum+i*p[index]);
    }
}
//主函数
int main(){
    scanf("%d %d",&n,&k);
    //去除重复数据输入并且写入重复的数量到哈希表中
    m=n;
    int t[MAX];
    for(int i=0;i<n;i++)
    {
        scanf("%d",&t[i]);
        hashTable[t[i]]++;
        if(i>0&&t[i]==t[i-1])
        {
            m--;
        }
    }
    int l=0;
    for(int i=0;i<MAXN;i++)
    {
        if(hashTable[i]!=0)
        {
            p[l]=i;
            l++;
        }
    }
    // printf("%d\n",m);
    // for(int i=0;i<m;i++)
    // {
    //     printf("%d ",p[i]);
    // }
    F(0,0);
    printf("%d",ans);
    system("pause");// 防止运行后自动退出，需头文件stdlib.h
    return 0;
}
```
+ 总结：这道题目的与上一道题目思路类似，巧妙之处同样在于设计了在循环中加上了本身的数据，随后根据加上了本身的数据再继续往后递归，不同点在于所能加上自身的数据从小于等于 `k` 变成了小于等于 `k` 和**输入的数据本身的数量**。

