+ 完整代码如下：
```cpp
#include <stdio.h>
#include <stdlib.h>
#include <stack>
#include <string>
#include <iostream>
#include <utility>
#include <map>
#include <algorithm>
#include <vector>
using namespace std;
const int MAX = 100010;
//A[]为递增序列，x为欲查询数，函数返回第一个大于等于x的元素位置
//二分区间为左闭右闭[left,right]，传入初值为[0,n]
int lower_bound(int A[],int left,int right,int x)
{
    int mid; //mid为left和right的中点
    while(left<right)
    {
        mid = (left+right)/2;//取中点
        if(A[mid]>=x)//中间的数大于等于x
        {
            right = mid;//往左区间[left,mid]查找
        }
        else
        {
            left = mid + 1;//往右子区间[mid+1,right]查找
        }
    }
    return left;//返回L(夹出来)的位置
}
//解决函数
int solve(int A[],int left,int right,int x,int n)
{
    //寻找断点
    while(A[0]>=A[n-1]&&left<right)
    {
        int mid=(left+right)/2;//取中点
        //printf("mid=%d\n",mid);
        if(A[mid]>A[left])
        {
            left=mid;
        }
        else
        {
            right=mid;
        }
    }
    int point=left;//存储断点
    //return left;
    //printf("point=%d\n",left);
    //判断目标元素在断点的左半边还是右半边
    if(x==A[0])
        return 0;
    else if(point!=0&&x>A[point])
        return -1;
    else if(point==0)
    {
        int ans=lower_bound(A,0,n,x);
        if(A[ans]==x)
            return ans;
        else
            return -1;
    }
    else if(x>A[0])//在左边
    {
        int ans=lower_bound(A,0,point,x);
        if(A[ans]==x)
            return ans;
        else
            return -1;
    }
    else//否则在右边
    {
        int ans=lower_bound(A,point,n-1,x);
        if(A[ans]==x)
            return ans;
        else
            return -1;
    }
}
//主函数
int main()
{
    int A[MAX];
    int x;
    int n,num;
    int ans;
    scanf("%d %d",&n,&x);
    for(int i=0;i<n;i++)
    {
        scanf("%d",&num);
        A[i]=num;
    }
    ans = solve(A,0,n-1,x,n);
    printf("%d",ans);
    system("pause");// 防止运行后自动退出，需头文件stdlib.h
    return 0;
}
```
