//处理函数
int solve(string str)
{
    int step=0,ou=0,ji=0,total=0;
    if(str=="123")
        return 0;
    else
    {
        while(1)
        {
            if(str=="123")
                break;
            else
            {
                for(int i=0;i<str.length();i++)
                {
                    if((str[i]-'0')%2==0)//偶数
