const int MAXN = 101;//表长
int prime[MAXN],pNum = 0;//prime数组存放所有素数，pNum为素数个数
bool p[MAXN] = {0};//p[i] == true表示i是素数

//判断是否为素数
bool isPrime(int n)
{
    if(n<=1)
        return false;//特判
    int sqr = (int)sqrt(1.0*n);//根号n
    for(int i=2;i<=sqr;i++)
    {
        if(n%i==0)
            return false;
    }
    return true;
