const int MAXN = 900000;//表长
int prime[MAXN],pNum = 0;//prime数组存放所有素数，pNum为素数个数
bool p[MAXN] = {false};//p[i] == true表示i是素数
int m,n;

//寻找素数表(素数筛法)
void Find_Prime_2()
{
	for(int i=2;i<MAXN;i++)//从2开始，i<MAXN结束
	{
		if(p[i] == false)//如果i是素数
        {
            prime[pNum++] = i;//把素数i存到prime数组中
            if(pNum>=n)
                break;
