using namespace std;

//求解最大公约数函数(递归算法)
int gcd(int a,int b)
{
    if(b==0)
        return a;
    else
        return gcd(b,a%b);
}

//扩展欧几里得算法
int exGcd(int a,int b,int &x,int &y)//x和y使用引用
{
	if(b==0)
	{
		x=1;
		y=0;
		return a;
	}
	int g = exGcd(b,a%b,x,y);//递归计算exGcd(b,a%b,x,y)
	int temp = x;//存放x的值
	x=y;//更新x=y(old)
	y=temp-a/b*y;//更新y=x(old)-a/b*y(old)
	return g;//g是gcd
}

//主函数
int main()
{
    int a,c,m;
    scanf("%d %d %d",&a,&c,&m);
    if(c%gcd(a,m)==0)
    {
        int x,y,g;
