#include <cstdio>
#include <string.h>
#include <iostream>
#include <algorithm>
using namespace std;
const int MAXN = 55;
//主函数
int main(){
    char str[MAXN][MAXN];
    int n;
    int min_strlen=100,num=0,flag=0;
    scanf("%d",&n);
    getchar();//吸收换行符
    for(int i=0;i<n;i++)
