        for(int k=0;k<n-1;k++)
        {
            if(str[k][i]!=str[k+1][i])
            {
                flag++;
            }
        }
        if(flag)
        {
            num=i-1;
            break;
        }
        num=i;
    }
    //printf("%d",min_strlen);
    for(int i=0;i<=num;i++)
    {
        printf("%c",str[0][i]);
