        temp.pop_back();
        F(index+1);
    }
}
//比较函数，从小到大排序
bool cmp(vector<int> &a,vector<int> &b)//引用的写法
{
    if(a.size()!=b.size())
        return a.size()<b.size();
    else
        return a<b;
}
