#include <cstdio>
#include <cstring>
#include <iostream>
#include <algorithm>
#include <cmath>
#include <string>
#include <vector>
using namespace std;
const int MAX = 300;
int n;
bool hashTable[MAX] = {false};
string str,temp;
vector<string> result;
//递归输出单词排序数
void F(int index)
{
    //递归边界
    if(index == n)
    {
