    return 0;
}
```
+ 输出：
```text
13 12 11 10 14 15
```
+ 如果是对容器中的元素（例如 `string` 字符串）进行反转，结果也一样：
```cpp
#include <stdio.h>
#include <stdlib.h>
#include <stack>
#include <string>
#include <iostream>
#include <utility>
#include <map>
#include <algorithm>
using namespace std;
//主函数
int main()
{
    string str = "abcdef";
    reverse(str.begin(),str.begin()+4);//将str[0]~str[3]反转
    for(int i=0;i<str.length();i++)
    {
        printf("%c",str[i]);
