#include <map>
#include <algorithm>
using namespace std;
//主函数
int main()
{
    int a[10] = {1,2,3,4,5};
    fill(a,a+5,888);//将a[0]~a[4]均赋值为888
    for(int i=0;i<5;i++)
    {
        printf("%d ",a[i]);
    }
    system("pause");// 防止运行后自动退出，需头文件stdlib.h
    return 0;
}
```
+ 输出：
```text
888 888 888 888 888
```
+ 对于二维数组的使用，示例如下：
```cpp
#include <stdio.h>
#include <stdlib.h>
#include <stack>
#include <string>
#include <iostream>
#include <utility>
#include <map>
#include <algorithm>
using namespace std;
//主函数
int main()
{
    int n=3,m=5;
    int a[n][m];
    int k;
    scanf("%d",&k);
    fill(a[0], a[0] + n * m, k);
