```cpp
#include <cstdio>
#include <string.h>
#include <iostream>
#include <algorithm>
using namespace std;
const int MAXN = 1100;
//结构体
struct stu{
    char name[20];
    int score;
    int kaochang;
    int paiming;
};
//比较函数
bool cmp1(stu a,stu b)
{
    return a.score>b.score;
}
bool cmp2(stu a,stu b)
{
        return strcmp(a.name,b.name)<0;
}
//主函数
int main(){
    int n,num_kaochang,sum=0,num[15];
    scanf("%d",&n);
    stu stu[MAXN];
    for(int i=0;i<n;i++)
    {
        scanf("%d",&num_kaochang);
        for(int k=sum;k<num_kaochang+sum;k++)
        {
            scanf("%s",stu[k].name);
            scanf("%d",&stu[k].score);
            stu[k].kaochang=i;
        }
        num[i]=num_kaochang;
        sort(stu+sum,stu+sum+num_kaochang, cmp1);
        stu[sum].paiming=1;
        for(int m=sum;m<sum+num_kaochang;m++)
        {
            if(stu[m].score==stu[m-1].score)
            {
                stu[m].paiming=stu[m-1].paiming;
            }
            else
            {
                stu[m].paiming=m+1-sum;//局部排名数值要减去sum
            }
        }
        sum+=num_kaochang;
    }
    sort(stu,stu+sum, cmp2);
    for(int i=0;i<sum;i++)
    {
        printf("%s %d %d\n",stu[i].name,stu[i].score,stu[i].paiming);
    }
    return 0;
}
```
