#include <cstdio>
#include <string.h>
#include <iostream>
#include <algorithm>
using namespace std;
const int MAXN = 1010;
char str[MAXN][5];
int hashTable[26*26*26+10]={0};
//字符串转Hash函数
int HashFunc(char s[],int len)
{
    int id=0;
    for(int i=0;i<len;i++)
    {
        id=id*26+(s[i]-'A');
    }
    return id;
}
//主函数
int main(){
    int n,m;
    scanf("%d",&n);
    for(int i=0;i<n;i++)
    {
        scanf("%s",str[i]);
        hashTable[HashFunc(str[i],3)]++;
    }
    scanf("%d",&m);
    for(int i=0;i<m;i++)
    {
        scanf("%s",str[i]);
        printf("%d",hashTable[HashFunc(str[i],3)]);
        if(i!=m-1)
        {
            printf(" ");
        }
    }
    return 0;
}
```
+ 总结：该题直接给出字符串散列的处理方法！重点掌握字符串转整数函数的编写和应用。

例题：[2-SUM-hash](https://sunnywhy.com/sfbj/4/2/104)
+ 代码：

```cpp
#include <cstdio>
#include <string.h>
#include <iostream>
#include <algorithm>
using namespace std;
const int MAXN = 1000001;
int num[MAXN]={0},hashTable[MAXN]={0};
//主函数
int main(){
    int n,k;
    scanf("%d %d",&n,&k);
    for(int i=0;i<n;i++)
    {
        scanf("%d",&num[i]);
        hashTable[num[i]]++;
    }
    int ans=0;
    for(int i=0;i<n;i++)
    {
        if(k-num[i]>=0&&hashTable[k-num[i]])
        {
            ans++;
        }
    }
    printf("%d",ans/2);
    return 0;
}
```
+ 总结：这道题目的巧妙之处在于通过用求和值`k`减去`a`后的值`b`是否还在**哈希表**中来判断是否满足条件。这样巧妙利用了**空间换时间**的思想，只用一次循环即可完成！最后注意最终结果需要再`÷2`！

### 递归
分治
+ 分治->"分而治之"
+ 分治法将原问题划分成若干个**规模较小**而**结构**与原问题**相同**或者**相似**的子问题，然后分别解决这些子问题，最后**合并**子问题的解，即可得到原问题的解。
  + 分解：将原问题划分成若干个**规模较小**而**结构**与原问题**相同**或者**相似**的子问题；
  + 解决：递归求解所有子问题。如果存在子问题的规模足够小就可以直接解决；
  + 合并：将子问题的解合并为原问题的解。
+ 分治法分解成的子问题应该是相互独立的、没有交叉的。
+ 分治法作为一种算法思想，既可以使用**递归**的手段去实现，也可以通过**非递归**的手段去实现。

递归
+ 递归在于**反复调用自身函数**，但是每次把**问题范围缩小**，直到范围缩小到可以直接得到边界数据的结果，然后再在返回的路上求出对应的解。
+ 递归很适合用来实现分治思想；
+ 递归的逻辑中一般有两个重要概念：
  + 递归边界
  + 递归式（或称递归调用）
+ 递归式是将原问题分解为若干个子问题的手段；
+ 递归边界是分解的尽头。
+ 例题->递归求解n的阶乘：

```cpp
#include <cstdio>
#include <string.h>
using namespace std;
//函数
int F(int n)
{
    if(n==0) return 1;//递归边界
    else return F(n-1)*n;//递归式
}
//主函数
int main(){
    int a=3;
    printf("%d",F(a));
    return 0;
}
```
+ 输出：

```
6
```
