    {
        Inteval in;
        scanf("%d %d",&in.x,&in.y);
        vi.push_back(in);
    }
    sort(vi.begin(),vi.end(),cmp);//把区间排序
    //ans记录不相交区间个数，lastX记录上一个被选中区间的左端点
    int ans = 1,lastX = vi[0].x;
    for(int i=1;i<n;i++)//从一开始循环,因为第一个自身天然算进去了
    {
        if(vi[i].y < lastX)//关键：如果该区间右端点lastX左边
        {
