#include <stdio.h>
#include <stdlib.h>
#include <stack>
#include <string>
#include <iostream>
#include <utility>
#include <map>
#include <algorithm>
#include <vector>
#include <climits>
#include <time.h>
using namespace std;

const int MAX = 1010;

//对区间[left,right]进行划分
int partition(int A[],int left,int right)
{
    //生成[left,right]内的随机数p
    srand((unsigned)time(NULL));//随机数种子
    int p = (int)((double)rand()/RAND_MAX*(right-left+1)+left);
    swap(A[p],A[left]);//交换A[p]和A[left]
    int temp = A[left];//将A[left]存至临时变量temp
    while(left<right)//只要left与right不相遇
    {
        while(left<right&&A[right]>temp)
            right--;//反复左移right
        A[left] = A[right];//将A[right]挪到A[left]
        while(left<right&&A[left]<=temp)
            left++;//反复右移left
        A[right] = A[left];//将A[left]挪到A[right]
    }
    A[left] = temp;//把temp放到left与right相遇的地方
    return left;//返回相遇的坐标
}

//快速排序，left与right初值为序列首尾下标(例如1和n)
void quickSort(int A[],int left,int right)
{
    if(left<right)//当前区间长度不超过1
    {
        //将[left,right]按照A[left]一分为二
        int pos = partition(A,left,right);
        quickSort(A,left,pos-1);//对左子区间递归进行快速排序
        quickSort(A,pos+1,right);//对右子区间递归进行快速排序
    }
}

//主函数
int main()
{
    int n,A[MAX];
    scanf("%d",&n);
    for(int i=0;i<n;i++)
    {
        scanf("%d",&A[i]);
    }
    quickSort(A,0,n-1);
    for(int i=0;i<n;i++)
    {
        printf("%d",A[i]);
        if(i<n-1)
            printf(" ");
    }
    printf("\n");
    system("pause");// 防止运行后自动退出，需头文件stdlib.h
    return 0;
}
