#### Simple_shell 的实现
+ 使用 `exec` 函数簇实现建议 `shell`：

```c
#include <unistd.h>
#include <stdio.h>
#include <stdlib.h>
#include <error.h>
#include <errno.h>
#include <fcntl.h>
#include <string.h>

#define MAXLINE 1024
#define MAXRGS 128

void print_wstatus(int status){
    if(WIFEXITED(status)){
        int exit_code = WEXITSTATUS(status);
        printf("exit_code = %d", exit_code);
    }
    else if(WIFSIGNALED(status)){
        int signo = WTERMSIG(status);
        printf("term_sig = %d", signo);
    }
#ifdef WCOREDUMP
    if(WCOREDUMP(status)){
        printf(" (core dump) ");
    }
#endif
    printf("\n");
}

// 解析命令行参数
void parse_parameters(char* message, char* argv[]){
    int i=0;
    argv[i] = strtok(message, " \t\n");
    while(argv[i] != NULL){
        i++;
        argv[i] = strtok(NULL, " \t\n");
    } // argv[i] == NULL
}

int main(int argc, char* argv[])
{
    char cmd[MAXLINE];
    char* parameters[MAXRGS];

    int status;

    for(;;){
        // 读取用户命令
        printf("Simple_shell > ");
        fgets(cmd, MAXLINE, stdin);
        // 如果cmd是exit，终止程序
        if(strcmp(cmd, "exit\n") == 0){
            exit(0);
        }
        // 创建子进程，让子进程执行命令
        pid_t pid = fork();

        switch(pid){
            case -1:
                error(1, errno, "fork");
            case 0: // 子进程
                // 解析命令行参数
                parse_parameters(cmd, parameters);
                if(execvp(parameters[0], parameters) == -1){
                    error(1, errno, "exevp");
                }
                break;
            default:
                if(waitpid(pid, &status, 0) == -1){
                    error(1, errno, "waitpid");
                }
                // 打印子进程的终止信息
                printf("%d terminated\n", pid);
                print_wstatus(status);
        }
    }
    return 0;
}
```

### 进程间通信
#### 管道 pipe
+ 管道：内核管理的一个数据结构
	+ 管道需要读端和写端都就绪，`open` 才会返回。
	+ 当写端写入数据时，`read` 才会返回，否则是阻塞状态。
	+ 如果写端关闭，读端是可以读到剩余数据，如果数据读完了，读端会读到 `EOF`（`read` 会返回 `0`）；
+ 创建管道：

![创建管道](https://yugin-blog-1313489805.cos.ap-guangzhou.myqcloud.com/20250701193043.png)

+ 进程间管道通信惯用法：
	+ 先 `pipe`
	+ 再 `fork`
	+ 父进程关闭管道一端
	+ 子进程关闭管道的另一端

![进程间管道通信惯用法](https://yugin-blog-1313489805.cos.ap-guangzhou.myqcloud.com/20250701193221.png)

+ 代码：

```c
#include <unistd.h>
#include <stdio.h>
#include <stdlib.h>
#include <error.h>
#include <errno.h>
#include <fcntl.h>
#include <string.h>

#define MAXLINE 1024

int main(int argc, char* argv[])
{
    // 先创建管道pipe
    int fields[2]; // fields[0]读端、fields[1]写端
    if(pipe(fields) == -1)
        error(1, errno, "pipe");
    // 再fork
    pid_t pid = fork();
    switch(pid){
        case -1:
            error(1, errno, "fork");
        case 0: // 子进程
            close(fields[1]);
            char message[MAXLINE];
            read(fields[0], message, MAXLINE);
            printf("child: %s",message);
            break;
        default: // 父进程
            close(fields[0]);
            sleep(5); // 管道为空会阻塞子进程
            write(fields[1], "This is parent!\n", 16+1); // +1 for '\0'
    }
    return 0;
}
```

