            printf("child_newfd = %d\n", newfd);
            exit(0);
        default:
            //父进程
            sleep(2);
            printf("parent_pos: %ld\n", lseek(fd, 0, SEEK_CUR));
            newfd = dup(fd); // newfd = 4
            printf("parent_newfd = %d\n", newfd);
            exit(0);
    }
    return 0;
}
