#include <signal.h>
#include <pthread.h>

typedef struct {
    int id;
    char name[25];
    char gender;
} Student;

void print_ids(const char* prefix){
    printf("%s: ", prefix);
    printf("pid = %d, ppid = %d ", getpid(), getppid());
    printf("tid = %lu\n", pthread_self());
}

// 子线程的执行流程
void* start_routine(void* args){
    Student* p = (Student*) args;
    // 在子线程中访问主线程栈里面的数据
    printf("%d %s %c\n",
        p->id,
        p->name,
        p->gender);
    print_ids("child_thread");
    return NULL;
}

int main(int argc, char* argv[])
{
