    print_ids("main_thread");

    Student s = {1, "yugin", 'm'};

    pthread_t tid;
    int err = pthread_create(&tid, NULL, start_routine, (void*)&s);
    if(err){
        error(1, err, "pthread_create");
    }

    printf("main: new_thread = %lu\n", tid);

    // 注意事项：当主线程终止时，整个进程就终止了
    sleep(2);
    return 0;
}
