    vector<vector<int>> graph(m, vector<int>(n, 0));
    vector<vector<bool>> visited(m, vector<bool>(n, false));
    for(int i=0; i<m; i++){
        for(int j=0; j<n; j++){
            scanf("%d", &graph[i][j]);
        }
    }
    // 代码逻辑部分
    for(int i=0; i<m; i++){
        if(graph[i][0] == 1)
            dfs(graph, i, 0);
        if(graph[i][n-1] == 1)
            dfs(graph, i, n-1);
    }
    for(int i=0; i<n; i++){
        if(graph[0][i] == 1)
            dfs(graph, 0, i);
        if(graph[m-1][i] == 1)
            dfs(graph, m-1, i);
    }
    int result = 0;
    for(int i=0; i<m; i++){
        for(int j=0; j<n; j++){
            if(graph[i][j] == 1){
                result++;
            }
        }
    }
    printf("%d\n", result);
    return 0;
}
```

