    void Traversal(TreeNode* root, vector<int>& ans){
        //终止条件
        if(root == nullptr)
            return;
        ans.push_back(root->val); 
        Traversal(root->left, ans); // 遍历左节点
        Traversal(root->right, ans); // 遍历右节点
    }

    vector<int> preorderTraversal(TreeNode* root) {
        vector<int> result;
        Traversal(root, result);
        return result;
    }
};
