                if(node->right)
                    st.push(node->right);
                //再入左节点，符合栈的顺序
                if(node->left)
                    st.push(node->left);
            }
            else{ // 遇到空节点表示将下一个节点加到结果向量中
                st.pop();
                node = st.top(); //重新取出栈顶元素
                st.pop();
                result.push_back(node->val);
            }
        }
        return result;
    }
